export const landLawCountryMarkup = [{"id":"madagascar","markup":"\u003csection class=\"country\" id=\"madagascar\"\u003e\r\n    \u003cdiv class=\"country-header\"\u003e\r\n      \u003cdiv class=\"country-flag\"\u003e\u0026#127474;\u0026#127468;\u003c/div\u003e\r\n      \u003cdiv class=\"country-title-block\"\u003e\r\n        \u003cdiv class=\"country-label\" data-t=\u0027{\"en\":\"Republic of Madagascar\",\"fr\":\"R\\u00e9publique de Madagascar\"}\u0027\u003eRepublic of Madagascar\u003c/div\u003e\r\n        \u003cdiv class=\"country-title\" data-t=\u0027{\"en\":\"Land Law in Madagascar\",\"fr\":\"Droit Foncier \\u00e0 Madagascar\"}\u0027\u003eLand Law in Madagascar\u003c/div\u003e\r\n        \u003cdiv class=\"country-subtitle\" data-t=\u0027{\"en\":\"Malagasy land tenure is among the most complex in Sub-Saharan Africa, historically shaped by French colonial law.\",\"fr\":\"Le r\\u00e9gime foncier malgache est parmi les plus complexes d\\u2019Afrique subsaharienne, historiquement fa\\u00e7onn\\u00e9 par le droit colonial fran\\u00e7ais.\"}\u0027\u003eMalagasy land tenure is among the most complex in Sub-Saharan Africa, historically shaped by French colonial law.\u003c/div\u003e\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"summary-card\"\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"All land in Madagascar that is not registered or privately titled is presumed to belong to the State. Foreign nationals cannot own land directly but may access it through long-term leases of up to 99 years.\",\"fr\":\"Toutes les terres \\u00e0 Madagascar qui ne sont pas enregistr\\u00e9es ou titr\\u00e9es sont pr\\u00e9sum\\u00e9es appartenir \\u00e0 l\\u2019\\u00c9tat. Les ressortissants \\u00e9trangers ne peuvent pas poss\\u00e9der de terres directement, mais peuvent y acc\\u00e9der par des baux \\u00e0 long terme d\\u2019une dur\\u00e9e maximale de 99 ans.\"}\u0027\u003eAll land in Madagascar that is not registered or privately titled is presumed to belong to the State. Foreign nationals cannot own land directly but may access it through long-term leases of up to 99 years.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Constitutional Framework\",\"fr\":\"Cadre Constitutionnel\"}\u0027\u003eConstitutional Framework\u003c/h3\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"The 2010 Constitution of Madagascar recognizes the right to property for Malagasy citizens. Foreign ownership of land is expressly prohibited by law. The state retains sovereign ownership over all unregistered land under the principle of domanialit\\u00e9.\",\"fr\":\"La Constitution de 2010 de Madagascar reconna\\u00eet le droit \\u00e0 la propri\\u00e9t\\u00e9 pour les citoyens malgaches. La propri\\u00e9t\\u00e9 fonci\\u00e8re \\u00e9trang\\u00e8re est express\\u00e9ment interdite par la loi. L\\u2019\\u00c9tat conserve la souverainet\\u00e9 sur toutes les terres non enregistr\\u00e9es en vertu du principe de domanialit\\u00e9.\"}\u0027\u003eThe 2010 Constitution of Madagascar recognizes the right to property for Malagasy citizens. Foreign ownership of land is expressly prohibited by law. The state retains sovereign ownership over all unregistered land under the principle of \u003cem\u003edomanialit\u0026eacute;\u003c/em\u003e.\u003c/p\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"Since the 2005\\u20132008 land reforms, Madagascar has modernized its system by introducing Certificats Fonciers (land certificates) as an alternative to the formal title deed, issued at the municipal level.\",\"fr\":\"Depuis les r\\u00e9formes fonci\\u00e8res de 2005\\u20132008, Madagascar a modernis\\u00e9 son syst\\u00e8me en introduisant des Certificats Fonciers comme alternative au titre de propri\\u00e9t\\u00e9 formel, \\u00e9mis au niveau municipal.\"}\u0027\u003eSince the 2005\u0026ndash;2008 land reforms, Madagascar has modernized its system by introducing \u003cem\u003eCertificats Fonciers\u003c/em\u003e (land certificates) as an alternative to the formal title deed, issued at the municipal level.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Key Legislation\",\"fr\":\"L\\u00e9gislation Principale\"}\u0027\u003eKey Legislation\u003c/h3\u003e\r\n      \u003ctable class=\"key-laws\"\u003e\r\n        \u003cthead\u003e\u003ctr\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Law / Decree\",\"fr\":\"Loi / D\\u00e9cret\"}\u0027\u003eLaw / Decree\u003c/th\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Year\",\"fr\":\"Ann\\u00e9e\"}\u0027\u003eYear\u003c/th\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Subject\",\"fr\":\"Objet\"}\u0027\u003eSubject\u003c/th\u003e\r\n        \u003c/tr\u003e\u003c/thead\u003e\r\n        \u003ctbody\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eOrdonnance n\u0026deg; 60-146\u003c/td\u003e\u003ctd\u003e1960\u003c/td\u003e\u003ctd data-t=\u0027{\"en\":\"General land tenure regime; establishes land registration system\",\"fr\":\"R\\u00e9gime foncier g\\u00e9n\\u00e9ral\\u00a0; \\u00e9tablit le syst\\u00e8me d\\u2019enregistrement foncier\"}\u0027\u003eGeneral land tenure regime; establishes land registration system\u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eLoi n\u0026deg; 2005-019\u003c/td\u003e\u003ctd\u003e2005\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Land Policy reform; recognition of local and customary tenure\",\"fr\":\"R\\u00e9forme de la politique fonci\\u00e8re\\u00a0; reconnaissance de la tenure locale et coutumi\\u00e8re\"}\u0027\u003eLand Policy reform; recognition of local and customary tenure\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://www.womenconnect.org/web/madagascar/access-to-inputs/-/asset_publisher/jtZ9je4LZiX3/content/acces-a-la-terre-a-madagascar\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"Summary \u0026amp; Context\",\"fr\":\"R\\u00e9sum\\u00e9 \u0026amp; Contexte\"}\u0027\u003eSummary \u0026amp; Context\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eLoi n\u0026deg; 2006-031\u003c/td\u003e\u003ctd\u003e2006\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Private unregistered land; introduces land certificates\",\"fr\":\"Terres priv\\u00e9es non enregistr\\u00e9es\\u00a0; introduit les certificats fonciers\"}\u0027\u003ePrivate unregistered land; introduces land certificates\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://www.global-regulation.com/translation/madagascar/5960978/law-no.-2006-031-establishing-the-legal-system-of-private-land-ownership-untitled.html\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"English Translation\",\"fr\":\"Traduction Anglaise\"}\u0027\u003eEnglish Translation\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eD\u0026eacute;cret n\u0026deg; 2007-1109\u003c/td\u003e\u003ctd\u003e2007\u003c/td\u003e\u003ctd data-t=\u0027{\"en\":\"Implementation of guichets fonciers (local land offices)\",\"fr\":\"Mise en \\u0153uvre des guichets fonciers (bureaux fonciers locaux)\"}\u0027\u003eImplementation of \u003cem\u003eguichets fonciers\u003c/em\u003e (local land offices)\u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eLoi n\u0026deg; 2008-014\u003c/td\u003e\u003ctd\u003e2008\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Foreign investment in agriculture and large-scale land use\",\"fr\":\"Investissement \\u00e9tranger dans l\\u2019agriculture et l\\u2019utilisation des terres \\u00e0 grande \\u00e9chelle\"}\u0027\u003eForeign investment in agriculture and large-scale land use\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://landportal.org/book/narratives/2021/madagascar\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"Land Portal Analysis\",\"fr\":\"Analyse Land Portal\"}\u0027\u003eLand Portal Analysis\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n        \u003c/tbody\u003e\r\n      \u003c/table\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"two-col\"\u003e\r\n      \u003cdiv class=\"info-box\"\u003e\r\n        \u003ch4 data-t=\u0027{\"en\":\"Citizen Rights\",\"fr\":\"Droits des Citoyens\"}\u0027\u003eCitizen Rights\u003c/h4\u003e\r\n        \u003cul\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Full freehold ownership rights\",\"fr\":\"Pleine propri\\u00e9t\\u00e9 fonci\\u00e8re\"}\u0027\u003eFull freehold ownership rights\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Can register land through formal titling\",\"fr\":\"Possibilit\\u00e9 d\\u2019enregistrer les terres par titrage formel\"}\u0027\u003eCan register land through formal titling\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Local land certificate recognized legally\",\"fr\":\"Certificat foncier local reconnu l\\u00e9galement\"}\u0027\u003eLocal land certificate recognized legally\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Customary rights protected under 2005 reform\",\"fr\":\"Droits coutumiers prot\\u00e9g\\u00e9s par la r\\u00e9forme de 2005\"}\u0027\u003eCustomary rights protected under 2005 reform\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Right to lease, mortgage, or transfer land\",\"fr\":\"Droit de louer, hypoth\\u00e9quer ou transf\\u00e9rer des terres\"}\u0027\u003eRight to lease, mortgage, or transfer land\u003c/li\u003e\r\n        \u003c/ul\u003e\r\n      \u003c/div\u003e\r\n      \u003cdiv class=\"info-box\"\u003e\r\n        \u003ch4 data-t=\u0027{\"en\":\"Foreign National Rights\",\"fr\":\"Droits des Ressortissants \\u00c9trangers\"}\u0027\u003eForeign National Rights\u003c/h4\u003e\r\n        \u003cul\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Cannot own land directly (prohibited by law)\",\"fr\":\"Ne peut pas poss\\u00e9der de terres directement (interdit par la loi)\"}\u0027\u003eCannot own land directly (prohibited by law)\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Long-term lease up to 99 years permitted\",\"fr\":\"Bail \\u00e0 long terme jusqu\\u2019\\u00e0 99 ans autoris\\u00e9\"}\u0027\u003eLong-term lease up to 99 years permitted\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"May own buildings, not the underlying land\",\"fr\":\"Peut poss\\u00e9der des b\\u00e2timents, pas le terrain sous-jacent\"}\u0027\u003eMay own buildings, not the underlying land\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Investments via Malagasy company possible\",\"fr\":\"Investissements via une soci\\u00e9t\\u00e9 malgache possibles\"}\u0027\u003eInvestments via Malagasy company possible\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Agricultural concessions subject to review\",\"fr\":\"Concessions agricoles soumises \\u00e0 examen\"}\u0027\u003eAgricultural concessions subject to review\u003c/li\u003e\r\n        \u003c/ul\u003e\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"alert\"\u003e\r\n      \u003cstrong data-t=\u0027{\"en\":\"Important Note\",\"fr\":\"Note Importante\"}\u0027\u003eImportant Note\u003c/strong\u003e\r\n      \u003cspan data-t=\u0027{\"en\":\"The 2009 political crisis halted a controversial 99-year lease of 1.3 million hectares to Daewoo Logistics, triggering significant national debate. Madagascar has since required parliamentary approval for large-scale foreign land concessions.\",\"fr\":\"La crise politique de 2009 a mis fin \\u00e0 un bail controvers\\u00e9 de 99 ans portant sur 1,3 million d\\u2019hectares accord\\u00e9 \\u00e0 Daewoo Logistics, d\\u00e9clenchant un important d\\u00e9bat national. Madagascar exige depuis lors l\\u2019approbation parlementaire pour les grandes concessions fonci\\u00e8res \\u00e9trang\\u00e8res.\"}\u0027\u003eThe 2009 political crisis halted a controversial 99-year lease of 1.3 million hectares to Daewoo Logistics, triggering significant national debate. Madagascar has since required parliamentary approval for large-scale foreign land concessions.\u003c/span\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"tags\"\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"State Land Presumption\",\"fr\":\"Pr\\u00e9somption Domaniale\"}\u0027\u003eState Land Presumption\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"99-Year Lease\",\"fr\":\"Bail de 99 Ans\"}\u0027\u003e99-Year Lease\u003c/span\u003e\r\n      \u003cspan class=\"tag\"\u003eCertificat Foncier\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"No Foreign Freehold\",\"fr\":\"Pas de Pleine Propri\\u00e9t\\u00e9 \\u00c9trang\\u00e8re\"}\u0027\u003eNo Foreign Freehold\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"2005 Land Reform\",\"fr\":\"R\\u00e9forme Fonci\\u00e8re 2005\"}\u0027\u003e2005 Land Reform\u003c/span\u003e\r\n    \u003c/div\u003e\r\n  \u003c/section\u003e"},{"id":"kenya","markup":"\u003csection class=\"country\" id=\"kenya\"\u003e\r\n    \u003cdiv class=\"country-header\"\u003e\r\n      \u003cdiv class=\"country-flag\"\u003e\u0026#127472;\u0026#127466;\u003c/div\u003e\r\n      \u003cdiv class=\"country-title-block\"\u003e\r\n        \u003cdiv class=\"country-label\" data-t=\u0027{\"en\":\"Republic of Kenya\",\"fr\":\"R\\u00e9publique du Kenya\"}\u0027\u003eRepublic of Kenya\u003c/div\u003e\r\n        \u003cdiv class=\"country-title\" data-t=\u0027{\"en\":\"Land Law in Kenya\",\"fr\":\"Droit Foncier au Kenya\"}\u0027\u003eLand Law in Kenya\u003c/div\u003e\r\n        \u003cdiv class=\"country-subtitle\" data-t=\u0027{\"en\":\"Kenya\\u2019s 2010 Constitution transformed land law with a three-tier classification system and strong citizenship protections.\",\"fr\":\"La Constitution k\\u00e9nyane de 2010 a transform\\u00e9 le droit foncier avec un syst\\u00e8me de classification \\u00e0 trois niveaux et de solides protections citoyennes.\"}\u0027\u003eKenya\u0026rsquo;s 2010 Constitution transformed land law with a three-tier classification system and strong citizenship protections.\u003c/div\u003e\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"summary-card\"\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"Kenya classifies land as public, community, or private. Foreigners may only hold land under leasehold (maximum 99 years). The Constitution explicitly prohibits freehold land ownership by non-citizens.\",\"fr\":\"Le Kenya classe les terres en terres publiques, communautaires ou priv\\u00e9es. Les \\u00e9trangers ne peuvent d\\u00e9tenir des terres que sous forme de bail (maximum 99 ans). La Constitution interdit explicitement la pleine propri\\u00e9t\\u00e9 fonci\\u00e8re par des non-citoyens.\"}\u0027\u003eKenya classifies land as public, community, or private. Foreigners may only hold land under leasehold (maximum 99 years). The Constitution explicitly prohibits freehold land ownership by non-citizens.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Constitutional Framework\",\"fr\":\"Cadre Constitutionnel\"}\u0027\u003eConstitutional Framework\u003c/h3\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"Article 65 of the 2010 Constitution restricts ownership of freehold land in Kenya to citizens only. Any land held by a non-citizen is automatically converted to leasehold on a term not exceeding 99 years. The National Land Commission, established under Article 67, manages public land and oversees historical land injustices.\",\"fr\":\"L\\u2019article 65 de la Constitution de 2010 r\\u00e9serve la pleine propri\\u00e9t\\u00e9 fonci\\u00e8re aux seuls citoyens k\\u00e9nyans. Toute terre d\\u00e9tenue par un non-citoyen est automatiquement convertie en bail d\\u2019une dur\\u00e9e maximale de 99 ans. La Commission nationale des terres, cr\\u00e9\\u00e9e par l\\u2019article 67, g\\u00e8re les terres publiques et supervise les injustices fonci\\u00e8res historiques.\"}\u0027\u003eArticle 65 of the 2010 Constitution restricts ownership of freehold land in Kenya to citizens only. Any land held by a non-citizen is automatically converted to leasehold on a term not exceeding 99 years. The National Land Commission, established under Article 67, manages public land and oversees historical land injustices.\u003c/p\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"Kenya\\u2019s land classification system distinguishes between public land (owned by the government), community land (owned by communities under customary law), and private land (individual freehold or leasehold).\",\"fr\":\"Le syst\\u00e8me de classification fonci\\u00e8re du Kenya distingue les terres publiques (appartenant \\u00e0 l\\u2019\\u00c9tat), les terres communautaires (appartenant aux communaut\\u00e9s selon le droit coutumier) et les terres priv\\u00e9es (propri\\u00e9t\\u00e9 individuelle en pleine propri\\u00e9t\\u00e9 ou en bail).\"}\u0027\u003eKenya\u0026rsquo;s land classification system distinguishes between public land (owned by the government), community land (owned by communities under customary law), and private land (individual freehold or leasehold).\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Key Legislation\",\"fr\":\"L\\u00e9gislation Principale\"}\u0027\u003eKey Legislation\u003c/h3\u003e\r\n      \u003ctable class=\"key-laws\"\u003e\r\n        \u003cthead\u003e\u003ctr\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Law / Decree\",\"fr\":\"Loi / D\\u00e9cret\"}\u0027\u003eLaw / Decree\u003c/th\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Year\",\"fr\":\"Ann\\u00e9e\"}\u0027\u003eYear\u003c/th\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Subject\",\"fr\":\"Objet\"}\u0027\u003eSubject\u003c/th\u003e\r\n        \u003c/tr\u003e\u003c/thead\u003e\r\n        \u003ctbody\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eConstitution of Kenya, Art. 61\u0026ndash;68\u003c/td\u003e\u003ctd\u003e2010\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Land classification, rights, and National Land Commission\",\"fr\":\"Classification des terres, droits et Commission nationale des terres\"}\u0027\u003eLand classification, rights, and National Land Commission\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://new.kenyalaw.org/akn/ke/act/2010/constitution/eng@2010-09-03\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"Kenya Law \\u2014 Full Text\",\"fr\":\"Kenya Law \\u2014 Texte Int\\u00e9gral\"}\u0027\u003eKenya Law \u0026mdash; Full Text\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eLand Act (No. 6 of 2012)\u003c/td\u003e\u003ctd\u003e2012\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Public and private land administration; leasehold terms\",\"fr\":\"Administration des terres publiques et priv\\u00e9es\\u00a0; conditions de bail\"}\u0027\u003ePublic and private land administration; leasehold terms\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://new.kenyalaw.org/akn/ke/act/2012/6/eng@2025-11-04\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"Kenya Law \\u2014 Full Text\",\"fr\":\"Kenya Law \\u2014 Texte Int\\u00e9gral\"}\u0027\u003eKenya Law \u0026mdash; Full Text\u003c/a\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://www.parliament.go.ke/sites/default/files/2017-05/LandAct2012.pdf\" target=\"_blank\" rel=\"noopener\"\u003ePDF\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eLand Registration Act (No. 3 of 2012)\u003c/td\u003e\u003ctd\u003e2012\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Consolidated land registration; replaces multiple older laws\",\"fr\":\"Enregistrement foncier consolid\\u00e9\\u00a0; remplace plusieurs anciennes lois\"}\u0027\u003eConsolidated land registration; replaces multiple older laws\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://eprocedures.investkenya.go.ke/media/Land_Registration_Act___No_3_of_2012_.pdf\" target=\"_blank\" rel=\"noopener\"\u003ePDF\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eCommunity Land Act (No. 27 of 2016)\u003c/td\u003e\u003ctd\u003e2016\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Recognition and protection of community land rights\",\"fr\":\"Reconnaissance et protection des droits fonciers communautaires\"}\u0027\u003eRecognition and protection of community land rights\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://new.kenyalaw.org/akn/ke/act/2016/27/eng@2016-09-09\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"Kenya Law \\u2014 Full Text\",\"fr\":\"Kenya Law \\u2014 Texte Int\\u00e9gral\"}\u0027\u003eKenya Law \u0026mdash; Full Text\u003c/a\u003e\r\n            \u003ca class=\"doc-link\" href=\"http://kenyalaw.org/kl/fileadmin/pdfdownloads/Acts/CommunityLandAct_27of2016.pdf\" target=\"_blank\" rel=\"noopener\"\u003ePDF\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eNational Land Commission Act (No. 5 of 2012)\u003c/td\u003e\u003ctd\u003e2012\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Powers and functions of the National Land Commission\",\"fr\":\"Pouvoirs et fonctions de la Commission nationale des terres\"}\u0027\u003ePowers and functions of the National Land Commission\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://landcommission.go.ke/land-laws/\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"NLC \\u2014 All Laws\",\"fr\":\"NLC \\u2014 Toutes les Lois\"}\u0027\u003eNLC \u0026mdash; All Laws\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n        \u003c/tbody\u003e\r\n      \u003c/table\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"two-col\"\u003e\r\n      \u003cdiv class=\"info-box\"\u003e\r\n        \u003ch4 data-t=\u0027{\"en\":\"Citizen Rights\",\"fr\":\"Droits des Citoyens\"}\u0027\u003eCitizen Rights\u003c/h4\u003e\r\n        \u003cul\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Full freehold ownership available\",\"fr\":\"Pleine propri\\u00e9t\\u00e9 disponible\"}\u0027\u003eFull freehold ownership available\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Leasehold (government land: 99 years max)\",\"fr\":\"Bail (terres domaniales\\u00a0: 99 ans max)\"}\u0027\u003eLeasehold (government land: 99 years max)\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Community land rights under customary law\",\"fr\":\"Droits fonciers communautaires selon la loi coutumierre\"}\u0027\u003eCommunity land rights under customary law\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Right to mortgage, sell, or bequeath\",\"fr\":\"Droit d\\u2019hypoth\\u00e9quer, vendre ou l\\u00e9guer\"}\u0027\u003eRight to mortgage, sell, or bequeath\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"First right of refusal on community land\",\"fr\":\"Droit de pr\\u00e9emption sur les terres communautaires\"}\u0027\u003eFirst right of refusal on community land\u003c/li\u003e\r\n        \u003c/ul\u003e\r\n      \u003c/div\u003e\r\n      \u003cdiv class=\"info-box\"\u003e\r\n        \u003ch4 data-t=\u0027{\"en\":\"Foreign National Rights\",\"fr\":\"Droits des Ressortissants \\u00c9trangers\"}\u0027\u003eForeign National Rights\u003c/h4\u003e\r\n        \u003cul\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Leasehold only \\u2014 max 99 years\",\"fr\":\"Bail uniquement \\u2014 99 ans maximum\"}\u0027\u003eLeasehold only \u0026mdash; max 99 years\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Freehold automatically converted to leasehold\",\"fr\":\"La pleine propri\\u00e9t\\u00e9 est automatiquement convertie en bail\"}\u0027\u003eFreehold automatically converted to leasehold\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Cannot hold community land\",\"fr\":\"Ne peut pas d\\u00e9tenir de terres communautaires\"}\u0027\u003eCannot hold community land\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Foreign companies may lease, not own\",\"fr\":\"Les soci\\u00e9t\\u00e9s \\u00e9trang\\u00e8res peuvent louer, pas poss\\u00e9der\"}\u0027\u003eForeign companies may lease, not own\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Spouse of citizen may not inherit freehold\",\"fr\":\"Le conjoint d\\u2019un citoyen ne peut pas h\\u00e9riter en pleine propri\\u00e9t\\u00e9\"}\u0027\u003eSpouse of citizen may not inherit freehold\u003c/li\u003e\r\n        \u003c/ul\u003e\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Land Dispute Resolution\",\"fr\":\"R\\u00e9solution des Litiges Fonciers\"}\u0027\u003eLand Dispute Resolution\u003c/h3\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"Kenya\\u2019s Environment and Land Court (ELC), established under Article 162(2)(b) of the Constitution, has exclusive jurisdiction over land and environment disputes. The court operates across all counties with specialized magistrates.\",\"fr\":\"Le Tribunal de l\\u2019environnement et des terres du Kenya (ELC), cr\\u00e9\\u00e9 en vertu de l\\u2019article 162(2)(b) de la Constitution, a comp\\u00e9tence exclusive sur les litiges fonciers et environnementaux. Il op\\u00e8re dans tous les comt\\u00e9s avec des magistrats sp\\u00e9cialis\\u00e9s.\"}\u0027\u003eKenya\u0026rsquo;s Environment and Land Court (ELC), established under Article 162(2)(b) of the Constitution, has exclusive jurisdiction over land and environment disputes. The court operates across all counties with specialized magistrates.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"alert\"\u003e\r\n      \u003cstrong data-t=\u0027{\"en\":\"Historical Land Injustices\",\"fr\":\"Injustices Fonci\\u00e8res Historiques\"}\u0027\u003eHistorical Land Injustices\u003c/strong\u003e\r\n      \u003cspan data-t=\u0027{\"en\":\"The National Land Commission is mandated under Section 15 of the NLC Act to investigate historical land injustices, including colonial-era forced displacements. Claims may be submitted to the Commission for review and restitution.\",\"fr\":\"La Commission nationale des terres est mandat\\u00e9e par l\\u2019article 15 de la loi NLC pour enqu\\u00eater sur les injustices fonci\\u00e8res historiques, y compris les d\\u00e9placements forc\\u00e9s de l\\u2019\\u00e8re coloniale. Les r\\u00e9clamations peuvent \\u00eatre soumises \\u00e0 la Commission pour examen et restitution.\"}\u0027\u003eThe National Land Commission is mandated under Section 15 of the NLC Act to investigate historical land injustices, including colonial-era forced displacements. Claims may be submitted to the Commission for review and restitution.\u003c/span\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"tags\"\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"No Foreign Freehold\",\"fr\":\"Pas de Pleine Propri\\u00e9t\\u00e9 \\u00c9trang\\u00e8re\"}\u0027\u003eNo Foreign Freehold\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"99-Year Leasehold\",\"fr\":\"Bail de 99 Ans\"}\u0027\u003e99-Year Leasehold\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"National Land Commission\",\"fr\":\"Commission Nationale des Terres\"}\u0027\u003eNational Land Commission\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"Community Land\",\"fr\":\"Terres Communautaires\"}\u0027\u003eCommunity Land\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"Environment \u0026amp; Land Court\",\"fr\":\"Tribunal de l\\u2019Environnement et des Terres\"}\u0027\u003eEnvironment \u0026amp; Land Court\u003c/span\u003e\r\n    \u003c/div\u003e\r\n  \u003c/section\u003e"},{"id":"tanzania","markup":"\u003csection class=\"country\" id=\"tanzania\"\u003e\r\n    \u003cdiv class=\"country-header\"\u003e\r\n      \u003cdiv class=\"country-flag\"\u003e\u0026#127481;\u0026#127487;\u003c/div\u003e\r\n      \u003cdiv class=\"country-title-block\"\u003e\r\n        \u003cdiv class=\"country-label\" data-t=\u0027{\"en\":\"United Republic of Tanzania\",\"fr\":\"R\\u00e9publique-Unie de Tanzanie\"}\u0027\u003eUnited Republic of Tanzania\u003c/div\u003e\r\n        \u003cdiv class=\"country-title\" data-t=\u0027{\"en\":\"Land Law in Tanzania\",\"fr\":\"Droit Foncier en Tanzanie\"}\u0027\u003eLand Law in Tanzania\u003c/div\u003e\r\n        \u003cdiv class=\"country-subtitle\" data-t=\u0027{\"en\":\"Tanzania operates one of the most restrictive foreign land ownership regimes in Africa \\u2014 all land belongs to the state.\",\"fr\":\"La Tanzanie applique l\\u2019un des r\\u00e9gimes de propri\\u00e9t\\u00e9 fonci\\u00e8re \\u00e9trang\\u00e8re les plus restrictifs d\\u2019Afrique \\u2014 toutes les terres appartiennent \\u00e0 l\\u2019\\u00c9tat.\"}\u0027\u003eTanzania operates one of the most restrictive foreign land ownership regimes in Africa \u0026mdash; all land belongs to the state.\u003c/div\u003e\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"summary-card\"\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"In Tanzania, all land is public property vested in the President as trustee for the citizens. No individual \\u2014 citizen or foreigner \\u2014 can own land in fee simple. Rights of occupancy are granted by the government.\",\"fr\":\"En Tanzanie, toutes les terres sont propri\\u00e9t\\u00e9 publique confi\\u00e9e au Pr\\u00e9sident en qualit\\u00e9 de fiduciaire pour les citoyens. Aucun individu \\u2014 citoyen ou \\u00e9tranger \\u2014 ne peut poss\\u00e9der de terres en pleine propri\\u00e9t\\u00e9. Les droits d\\u2019occupation sont accord\\u00e9s par le gouvernement.\"}\u0027\u003eIn Tanzania, all land is public property vested in the President as trustee for the citizens. No individual \u0026mdash; citizen or foreigner \u0026mdash; can own land in fee simple. Rights of occupancy are granted by the government.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Constitutional Framework\",\"fr\":\"Cadre Constitutionnel\"}\u0027\u003eConstitutional Framework\u003c/h3\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"Tanzania\\u2019s land ownership model is rooted in the Arusha Declaration of 1967, which nationalized all land. The 1995 Land Policy reaffirmed that all land is public land held in trust by the President. Citizens hold land through a right of occupancy \\u2014 a leasehold interest granted for 33, 66, or 99 years, renewable upon expiry.\",\"fr\":\"Le mod\\u00e8le tanzanien de propri\\u00e9t\\u00e9 fonci\\u00e8re est ancr\\u00e9 dans la D\\u00e9claration d\\u2019Arusha de 1967, qui a nationalis\\u00e9 toutes les terres. La Politique fonci\\u00e8re de 1995 a r\\u00e9affirm\\u00e9 que toutes les terres sont des terres publiques d\\u00e9tenues en fiducie par le Pr\\u00e9sident. Les citoyens d\\u00e9tiennent les terres via un droit d\\u2019occupation \\u2014 un int\\u00e9r\\u00eat de bail accord\\u00e9 pour 33, 66 ou 99 ans, renouvelable \\u00e0 l\\u2019expiration.\"}\u0027\u003eTanzania\u0026rsquo;s land ownership model is rooted in the Arusha Declaration of 1967, which nationalized all land. The 1995 Land Policy reaffirmed that all land is public land held in trust by the President. Citizens hold land through a \u003cem\u003eright of occupancy\u003c/em\u003e \u0026mdash; a leasehold interest granted for 33, 66, or 99 years, renewable upon expiry.\u003c/p\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"Foreigners can only access land for investment purposes under a derivative right sub-leased from a citizen or the Tanzania Investment Centre (TIC).\",\"fr\":\"Les \\u00e9trangers ne peuvent acc\\u00e9der aux terres qu\\u2019\\u00e0 des fins d\\u2019investissement via un droit d\\u00e9riv\\u00e9 sous-lou\\u00e9 \\u00e0 un citoyen ou au Centre d\\u2019investissement de Tanzanie (TIC).\"}\u0027\u003eForeigners can only access land for investment purposes under a \u0026ldquo;derivative right\u0026rdquo; sub-leased from a citizen or the Tanzania Investment Centre (TIC).\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Key Legislation\",\"fr\":\"L\\u00e9gislation Principale\"}\u0027\u003eKey Legislation\u003c/h3\u003e\r\n      \u003ctable class=\"key-laws\"\u003e\r\n        \u003cthead\u003e\u003ctr\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Law / Decree\",\"fr\":\"Loi / D\\u00e9cret\"}\u0027\u003eLaw / Decree\u003c/th\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Year\",\"fr\":\"Ann\\u00e9e\"}\u0027\u003eYear\u003c/th\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Subject\",\"fr\":\"Objet\"}\u0027\u003eSubject\u003c/th\u003e\r\n        \u003c/tr\u003e\u003c/thead\u003e\r\n        \u003ctbody\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eLand Act (Cap. 113)\u003c/td\u003e\u003ctd\u003e1999\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"General land (non-village); rights of occupancy; land administration\",\"fr\":\"Terres g\\u00e9n\\u00e9rales (non villageoises)\\u00a0; droits d\\u2019occupation\\u00a0; administration fonci\\u00e8re\"}\u0027\u003eGeneral land (non-village); rights of occupancy; land administration\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://tanzlii.org/akn/tz/act/1999/4/eng@2019-11-30\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"TanzLII \\u2014 Full Text\",\"fr\":\"TanzLII \\u2014 Texte Int\\u00e9gral\"}\u0027\u003eTanzLII \u0026mdash; Full Text\u003c/a\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://media.tanzlii.org/files/legislation/akn-tz-act-1999-4-eng-2019-11-30.pdf\" target=\"_blank\" rel=\"noopener\"\u003ePDF\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eVillage Land Act (Cap. 114)\u003c/td\u003e\u003ctd\u003e1999\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Village land rights; customary occupancy; village councils\",\"fr\":\"Droits fonciers villageois\\u00a0; occupation coutumierre\\u00a0; conseils de village\"}\u0027\u003eVillage land rights; customary occupancy; village councils\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://tanzlii.org/akn/tz/act/1999/5/eng@2019-11-30\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"TanzLII \\u2014 Full Text\",\"fr\":\"TanzLII \\u2014 Texte Int\\u00e9gral\"}\u0027\u003eTanzLII \u0026mdash; Full Text\u003c/a\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://media.tanzlii.org/files/legislation/akn-tz-act-1999-5-eng-2019-11-30.pdf\" target=\"_blank\" rel=\"noopener\"\u003ePDF\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eLand Registration Act (Cap. 334)\u003c/td\u003e\u003ctd\u003e1953 (rev.)\u003c/td\u003e\u003ctd data-t=\u0027{\"en\":\"Registration of land interests and dealings\",\"fr\":\"Enregistrement des droits et transactions fonci\\u00e8res\"}\u0027\u003eRegistration of land interests and dealings\u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eTanzania Investment Act (Cap. 38)\u003c/td\u003e\u003ctd\u003e1997\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Foreign investment in land via TIC derivative rights\",\"fr\":\"Investissement \\u00e9tranger dans les terres via les droits d\\u00e9riv\\u00e9s du TIC\"}\u0027\u003eForeign investment in land via TIC derivative rights\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"http://parliament.go.tz/polis/uploads/bills/acts/1457511408-ActNo-5-1999.pdf\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"Parliament PDF\",\"fr\":\"PDF du Parlement\"}\u0027\u003eParliament PDF\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eUrban Planning Act (Cap. 355)\u003c/td\u003e\u003ctd\u003e2007\u003c/td\u003e\u003ctd data-t=\u0027{\"en\":\"Urban land use planning and development control\",\"fr\":\"Planification de l\\u2019utilisation des terres urbaines et contr\\u00f4le du d\\u00e9veloppement\"}\u0027\u003eUrban land use planning and development control\u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eLand Disputes Courts Act (Cap. 216)\u003c/td\u003e\u003ctd\u003e2002\u003c/td\u003e\u003ctd data-t=\u0027{\"en\":\"Establishment of land dispute courts and mediation\",\"fr\":\"Cr\\u00e9ation des tribunaux fonciers et m\\u00e9diation\"}\u0027\u003eEstablishment of land dispute courts and mediation\u003c/td\u003e\u003c/tr\u003e\r\n        \u003c/tbody\u003e\r\n      \u003c/table\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"two-col\"\u003e\r\n      \u003cdiv class=\"info-box\"\u003e\r\n        \u003ch4 data-t=\u0027{\"en\":\"Citizen Rights\",\"fr\":\"Droits des Citoyens\"}\u0027\u003eCitizen Rights\u003c/h4\u003e\r\n        \u003cul\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Right of occupancy (granted rights, not ownership)\",\"fr\":\"Droit d\\u2019occupation (droits accord\\u00e9s, pas propri\\u00e9t\\u00e9)\"}\u0027\u003eRight of occupancy (granted rights, not ownership)\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Customary right of occupancy in villages\",\"fr\":\"Droit d\\u2019occupation coutumier dans les villages\"}\u0027\u003eCustomary right of occupancy in villages\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"33, 66, or 99-year occupancy terms\",\"fr\":\"Dur\\u00e9es d\\u2019occupation de 33, 66 ou 99 ans\"}\u0027\u003e33, 66, or 99-year occupancy terms\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Can mortgage, transfer, or sub-lease rights\",\"fr\":\"Peut hypoth\\u00e9quer, transf\\u00e9rer ou sous-louer les droits\"}\u0027\u003eCan mortgage, transfer, or sub-lease rights\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Village councils govern community land\",\"fr\":\"Les conseils de village g\\u00e8rent les terres communautaires\"}\u0027\u003eVillage councils govern community land\u003c/li\u003e\r\n        \u003c/ul\u003e\r\n      \u003c/div\u003e\r\n      \u003cdiv class=\"info-box\"\u003e\r\n        \u003ch4 data-t=\u0027{\"en\":\"Foreign National Rights\",\"fr\":\"Droits des Ressortissants \\u00c9trangers\"}\u0027\u003eForeign National Rights\u003c/h4\u003e\r\n        \u003cul\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Cannot hold a right of occupancy directly\",\"fr\":\"Ne peut pas d\\u00e9tenir un droit d\\u2019occupation directement\"}\u0027\u003eCannot hold a right of occupancy directly\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Derivative right via TIC for investment only\",\"fr\":\"Droit d\\u00e9riv\\u00e9 via le TIC pour investissement uniquement\"}\u0027\u003eDerivative right via TIC for investment only\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Must demonstrate productive investment use\",\"fr\":\"Doit d\\u00e9montrer un usage d\\u2019investissement productif\"}\u0027\u003eMust demonstrate productive investment use\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Land reverts if investment conditions not met\",\"fr\":\"Le terrain revient si les conditions d\\u2019investissement ne sont pas remplies\"}\u0027\u003eLand reverts if investment conditions not met\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Zanzibar has a separate (slightly different) regime\",\"fr\":\"Zanzibar dispose d\\u2019un r\\u00e9gime s\\u00e9par\\u00e9 (l\\u00e9g\\u00e8rement diff\\u00e9rent)\"}\u0027\u003eZanzibar has a separate (slightly different) regime\u003c/li\u003e\r\n        \u003c/ul\u003e\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Zanzibar Special Regime\",\"fr\":\"R\\u00e9gime Sp\\u00e9cial de Zanzibar\"}\u0027\u003eZanzibar Special Regime\u003c/h3\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"Zanzibar (comprising Unguja and Pemba islands) has its own land laws under the Zanzibar Land Tenure Act No. 12 of 1992. Foreigners may acquire a Certificate of Granted Right of Occupancy for up to 33 years for approved residential or tourism projects via ZIPA.\",\"fr\":\"Zanzibar (comprenant les \\u00eeles d\\u2019Unguja et Pemba) dispose de ses propres lois fonci\\u00e8res en vertu de la Loi zanzibarite sur la tenure fonci\\u00e8re n\\u00b0 12 de 1992. Les \\u00e9trangers peuvent acqu\\u00e9rir un Certificat de droit d\\u2019occupation accord\\u00e9 pour une dur\\u00e9e maximale de 33 ans pour des projets r\\u00e9sidentiels ou touristiques approuv\\u00e9s via la ZIPA.\"}\u0027\u003eZanzibar (comprising Unguja and Pemba islands) has its own land laws under the Zanzibar Land Tenure Act No. 12 of 1992. Foreigners may acquire a Certificate of Granted Right of Occupancy for up to 33 years for approved residential or tourism projects via ZIPA.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"alert\"\u003e\r\n      \u003cstrong data-t=\u0027{\"en\":\"Village Land \u0026amp; Investment Conflicts\",\"fr\":\"Terres Villageoises et Conflits d\\u2019Investissement\"}\u0027\u003eVillage Land \u0026amp; Investment Conflicts\u003c/strong\u003e\r\n      \u003cspan data-t=\u0027{\"en\":\"Large-scale agricultural investments in Tanzania have historically led to conflicts with village communities regarding the conversion of village land for foreign investor use. The Land Acquisition Act (Cap. 118) governs compulsory acquisition and requires fair and prompt compensation.\",\"fr\":\"Les investissements agricoles \\u00e0 grande \\u00e9chelle en Tanzanie ont historiquement engendr\\u00e9 des conflits avec les communaut\\u00e9s villageoises concernant la conversion de terres villageoises pour l\\u2019usage d\\u2019investisseurs \\u00e9trangers. La Loi sur l\\u2019acquisition des terres (Cap. 118) r\\u00e9git l\\u2019acquisition obligatoire et exige une indemnisation juste et rapide.\"}\u0027\u003eLarge-scale agricultural investments in Tanzania have historically led to conflicts with village communities regarding the conversion of village land for foreign investor use. The Land Acquisition Act (Cap. 118) governs compulsory acquisition and requires fair and prompt compensation.\u003c/span\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"tags\"\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"State Ownership of All Land\",\"fr\":\"Propri\\u00e9t\\u00e9 \\u00c9tatique de Toutes les Terres\"}\u0027\u003eState Ownership of All Land\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"Right of Occupancy\",\"fr\":\"Droit d\\u2019Occupation\"}\u0027\u003eRight of Occupancy\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"TIC Derivative Right\",\"fr\":\"Droit D\\u00e9riv\\u00e9 TIC\"}\u0027\u003eTIC Derivative Right\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"99-Year Maximum\",\"fr\":\"Maximum 99 Ans\"}\u0027\u003e99-Year Maximum\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"Zanzibar Separate Regime\",\"fr\":\"R\\u00e9gime S\\u00e9par\\u00e9 Zanzibar\"}\u0027\u003eZanzibar Separate Regime\u003c/span\u003e\r\n    \u003c/div\u003e\r\n  \u003c/section\u003e"},{"id":"mauritius","markup":"\u003csection class=\"country\" id=\"mauritius\"\u003e\r\n    \u003cdiv class=\"country-header\"\u003e\r\n      \u003cdiv class=\"country-flag\"\u003e\u0026#127474;\u0026#127482;\u003c/div\u003e\r\n      \u003cdiv class=\"country-title-block\"\u003e\r\n        \u003cdiv class=\"country-label\" data-t=\u0027{\"en\":\"Republic of Mauritius\",\"fr\":\"R\\u00e9publique de Maurice\"}\u0027\u003eRepublic of Mauritius\u003c/div\u003e\r\n        \u003cdiv class=\"country-title\" data-t=\u0027{\"en\":\"Land Law in Mauritius\",\"fr\":\"Droit Foncier \\u00e0 Maurice\"}\u0027\u003eLand Law in Mauritius\u003c/div\u003e\r\n        \u003cdiv class=\"country-subtitle\" data-t=\u0027{\"en\":\"Mauritius offers the most open foreign land ownership framework in the region, especially through structured investment schemes.\",\"fr\":\"Maurice offre le cadre le plus ouvert pour la propri\\u00e9t\\u00e9 fonci\\u00e8re \\u00e9trang\\u00e8re dans la r\\u00e9gion, notamment \\u00e0 travers des r\\u00e9gimes d\\u2019investissement structur\\u00e9s.\"}\u0027\u003eMauritius offers the most open foreign land ownership framework in the region, especially through structured investment schemes.\u003c/div\u003e\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"summary-card\"\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"Mauritius uniquely allows foreigners to purchase property and acquire permanent residency through approved investment schemes. However, general freehold land purchase by non-citizens remains restricted outside designated programmes.\",\"fr\":\"Maurice permet exceptionnellement aux \\u00e9trangers d\\u2019acheter des biens immobiliers et d\\u2019acqu\\u00e9rir la r\\u00e9sidence permanente via des r\\u00e9gimes d\\u2019investissement approuv\\u00e9s. Cependant, l\\u2019achat g\\u00e9n\\u00e9ral de terres en pleine propri\\u00e9t\\u00e9 par des non-citoyens reste limit\\u00e9 en dehors des programmes d\\u00e9sign\\u00e9s.\"}\u0027\u003eMauritius uniquely allows foreigners to purchase property and acquire permanent residency through approved investment schemes. However, general freehold land purchase by non-citizens remains restricted outside designated programmes.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Constitutional Framework\",\"fr\":\"Cadre Constitutionnel\"}\u0027\u003eConstitutional Framework\u003c/h3\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"The Constitution of Mauritius (1968) protects the right to property under Section 8. Mauritius follows a hybrid civil law and common law system inherited from French and British colonial influences. The Civil Code of Mauritius (based on the Napoleonic Code) governs most property transactions.\",\"fr\":\"La Constitution de Maurice (1968) prot\\u00e8ge le droit \\u00e0 la propri\\u00e9t\\u00e9 en vertu de l\\u2019article 8. Maurice suit un syst\\u00e8me hybride de droit civil et de common law h\\u00e9rit\\u00e9 des influences coloniales fran\\u00e7aises et britanniques. Le Code civil de Maurice (inspir\\u00e9 du Code Napol\\u00e9on) r\\u00e9git la plupart des transactions immobili\\u00e8res.\"}\u0027\u003eThe Constitution of Mauritius (1968) protects the right to property under Section 8. Mauritius follows a hybrid civil law and common law system inherited from French and British colonial influences. The Civil Code of Mauritius (based on the Napoleonic Code) governs most property transactions.\u003c/p\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"Mauritius has progressively liberalized its property regime through the Integrated Resort Scheme (IRS), Real Estate Scheme (RES), and Property Development Scheme (PDS) as the main gateways for foreign property ownership.\",\"fr\":\"Maurice a progressivement lib\\u00e9ralis\\u00e9 son r\\u00e9gime immobilier \\u00e0 travers le R\\u00e9gime des R\\u00e9sidences Int\\u00e9gr\\u00e9es (IRS), le R\\u00e9gime Immobilier (RES) et le R\\u00e9gime de D\\u00e9veloppement Immobilier (PDS) comme principales voies d\\u2019acc\\u00e8s \\u00e0 la propri\\u00e9t\\u00e9 \\u00e9trang\\u00e8re.\"}\u0027\u003eMauritius has progressively liberalized its property regime through the \u003cem\u003eIntegrated Resort Scheme (IRS)\u003c/em\u003e, \u003cem\u003eReal Estate Scheme (RES)\u003c/em\u003e, and \u003cem\u003eProperty Development Scheme (PDS)\u003c/em\u003e as the main gateways for foreign property ownership.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Key Legislation\",\"fr\":\"L\\u00e9gislation Principale\"}\u0027\u003eKey Legislation\u003c/h3\u003e\r\n      \u003ctable class=\"key-laws\"\u003e\r\n        \u003cthead\u003e\u003ctr\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Law / Decree\",\"fr\":\"Loi / D\\u00e9cret\"}\u0027\u003eLaw / Decree\u003c/th\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Year\",\"fr\":\"Ann\\u00e9e\"}\u0027\u003eYear\u003c/th\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Subject\",\"fr\":\"Objet\"}\u0027\u003eSubject\u003c/th\u003e\r\n        \u003c/tr\u003e\u003c/thead\u003e\r\n        \u003ctbody\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eNon-Citizens (Property Restriction) Act\u003c/td\u003e\u003ctd\u003e1975\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Restrictions on non-citizen property acquisition outside approved schemes\",\"fr\":\"Restrictions \\u00e0 l\\u2019acquisition immobili\\u00e8re par des non-citoyens hors r\\u00e9gimes approuv\\u00e9s\"}\u0027\u003eRestrictions on non-citizen property acquisition outside approved schemes\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://lawsofmauritius.govmu.org/portal/viewlegislationdocument/web/?doctitle=Tm9uLWNpdGl6ZW5zIChQcm9wZXJ0eSBSZXN0cmljdGlvbikgQWN0\u0026docnumber=\u0026doctype=act\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"Laws of Mauritius \\u2014 Full Text\",\"fr\":\"Lois de Maurice \\u2014 Texte Int\\u00e9gral\"}\u0027\u003eLaws of Mauritius \u0026mdash; Full Text\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eCode Civil de Maurice\u003c/td\u003e\u003ctd\u003e1808\u003c/td\u003e\u003ctd data-t=\u0027{\"en\":\"General property law, contracts, and real rights\",\"fr\":\"Droit de propri\\u00e9t\\u00e9 g\\u00e9n\\u00e9ral, contrats et droits r\\u00e9els\"}\u0027\u003eGeneral property law, contracts, and real rights\u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eInvestment Promotion Act\u003c/td\u003e\u003ctd\u003e2000\u003c/td\u003e\u003ctd data-t=\u0027{\"en\":\"Framework for IRS, RES, and PDS investment schemes\",\"fr\":\"Cadre pour les r\\u00e9gimes d\\u2019investissement IRS, RES et PDS\"}\u0027\u003eFramework for IRS, RES, and PDS investment schemes\u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eEconomic Development Board Act\u003c/td\u003e\u003ctd\u003e2017\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Establishment of EDB; oversight of investment schemes\",\"fr\":\"Cr\\u00e9ation de l\\u2019EDB\\u00a0; supervision des r\\u00e9gimes d\\u2019investissement\"}\u0027\u003eEstablishment of EDB; oversight of investment schemes\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://edbmauritius.org/wp-content/uploads/2022/10/EDB-PDS-regulations.pdf\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"PDS Regulations PDF\",\"fr\":\"PDF R\\u00e8glement PDS\"}\u0027\u003ePDS Regulations PDF\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eLand (Duties and Taxes) Act\u003c/td\u003e\u003ctd\u003e1984\u003c/td\u003e\u003ctd data-t=\u0027{\"en\":\"Transfer duties, registration fees, and taxes on land transactions\",\"fr\":\"Droits de mutation, frais d\\u2019enregistrement et taxes sur les transactions fonci\\u00e8res\"}\u0027\u003eTransfer duties, registration fees, and taxes on land transactions\u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eMorcellement Act\u003c/td\u003e\u003ctd\u003e2001\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Subdivision and development of land; permit requirements\",\"fr\":\"Morcellement et d\\u00e9veloppement des terres\\u00a0; conditions de permis\"}\u0027\u003eSubdivision and development of land; permit requirements\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://edbmauritius.org/wp-content/uploads/2024/05/Guidelines-PDS.pdf\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"EDB Buyer Guidelines PDF\",\"fr\":\"PDF Guide Acheteur EDB\"}\u0027\u003eEDB Buyer Guidelines PDF\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n        \u003c/tbody\u003e\r\n      \u003c/table\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Foreign Investment Schemes\",\"fr\":\"R\\u00e9gimes d\\u2019Investissement \\u00c9tranger\"}\u0027\u003eForeign Investment Schemes\u003c/h3\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"The Property Development Scheme (PDS), which replaced IRS and RES in 2015, allows foreigners to purchase residential units of at least USD 375,000, qualifying them for Mauritian Permanent Residency. Developers must allocate 25% of land to social housing or contribute to a social amenities fund.\",\"fr\":\"Le R\\u00e9gime de D\\u00e9veloppement Immobilier (PDS), qui a remplac\\u00e9 l\\u2019IRS et le RES en 2015, permet aux \\u00e9trangers d\\u2019acqu\\u00e9rir des unit\\u00e9s r\\u00e9sidentielles d\\u2019au moins 375\\u00a0000 USD, leur ouvrant droit \\u00e0 la r\\u00e9sidence permanente mauricienne. Les promoteurs doivent consacrer 25\\u00a0% des terres au logement social ou contribuer \\u00e0 un fonds d\\u2019\\u00e9quipements collectifs.\"}\u0027\u003eThe \u003cstrong\u003eProperty Development Scheme (PDS)\u003c/strong\u003e, which replaced IRS and RES in 2015, allows foreigners to purchase residential units of at least USD 375,000, qualifying them for Mauritian Permanent Residency. Developers must allocate 25% of land to social housing or contribute to a social amenities fund.\u003c/p\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"The Smart City Scheme allows foreigners to purchase residential and commercial units in approved smart city developments, with residency benefits linked to investment thresholds above USD 500,000. The G+2 Scheme allows non-citizens to purchase apartments in buildings of at least three stories.\",\"fr\":\"Le R\\u00e9gime Smart City permet aux \\u00e9trangers d\\u2019acqu\\u00e9rir des unit\\u00e9s r\\u00e9sidentielles et commerciales dans des d\\u00e9veloppements smart city approuv\\u00e9s, avec des avantages de r\\u00e9sidence li\\u00e9s \\u00e0 des seuils d\\u2019investissement sup\\u00e9rieurs \\u00e0 500\\u00a0000 USD. Le R\\u00e9gime G+2 permet aux non-citoyens d\\u2019acheter des appartements dans des immeubles d\\u2019au moins trois \\u00e9tages.\"}\u0027\u003eThe \u003cstrong\u003eSmart City Scheme\u003c/strong\u003e allows foreigners to purchase residential and commercial units in approved smart city developments, with residency benefits linked to investment thresholds above USD 500,000. The \u003cstrong\u003eG+2 Scheme\u003c/strong\u003e allows non-citizens to purchase apartments in buildings of at least three stories.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"two-col\"\u003e\r\n      \u003cdiv class=\"info-box\"\u003e\r\n        \u003ch4 data-t=\u0027{\"en\":\"Citizen Rights\",\"fr\":\"Droits des Citoyens\"}\u0027\u003eCitizen Rights\u003c/h4\u003e\r\n        \u003cul\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Full freehold ownership rights\",\"fr\":\"Pleine propri\\u00e9t\\u00e9 fonci\\u00e8re\"}\u0027\u003eFull freehold ownership rights\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Purchase any land or property freely\",\"fr\":\"Acheter librement tout terrain ou bien immobilier\"}\u0027\u003ePurchase any land or property freely\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Entitled to agricultural land acquisition\",\"fr\":\"Droit d\\u2019acqu\\u00e9rir des terres agricoles\"}\u0027\u003eEntitled to agricultural land acquisition\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"No approval required for local purchases\",\"fr\":\"Aucune approbation requise pour les achats locaux\"}\u0027\u003eNo approval required for local purchases\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Subject to standard registration duties\",\"fr\":\"Soumis aux droits d\\u2019enregistrement standard\"}\u0027\u003eSubject to standard registration duties\u003c/li\u003e\r\n        \u003c/ul\u003e\r\n      \u003c/div\u003e\r\n      \u003cdiv class=\"info-box\"\u003e\r\n        \u003ch4 data-t=\u0027{\"en\":\"Foreign National Rights\",\"fr\":\"Droits des Ressortissants \\u00c9trangers\"}\u0027\u003eForeign National Rights\u003c/h4\u003e\r\n        \u003cul\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"PDS units \\u2265 USD 375,000 (+ residency)\",\"fr\":\"Unit\\u00e9s PDS \\u2265 375\\u00a0000 USD (+ r\\u00e9sidence)\"}\u0027\u003ePDS units \u0026ge; USD 375,000 (+ residency)\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Smart City commercial/residential units\",\"fr\":\"Unit\\u00e9s commerciales/r\\u00e9sidentielles Smart City\"}\u0027\u003eSmart City commercial/residential units\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"G+2 apartments in approved buildings\",\"fr\":\"Appartements G+2 dans les immeubles approuv\\u00e9s\"}\u0027\u003eG+2 apartments in approved buildings\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Leasehold for industrial use via EDB\",\"fr\":\"Bail pour usage industriel via l\\u2019EDB\"}\u0027\u003eLeasehold for industrial use via EDB\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Requires Economic Development Board approval\",\"fr\":\"N\\u00e9cessite l\\u2019approbation du Conseil de d\\u00e9veloppement \\u00e9conomique\"}\u0027\u003eRequires Economic Development Board approval\u003c/li\u003e\r\n        \u003c/ul\u003e\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"alert\"\u003e\r\n      \u003cstrong data-t=\u0027{\"en\":\"Residency Benefit\",\"fr\":\"Avantage de R\\u00e9sidence\"}\u0027\u003eResidency Benefit\u003c/strong\u003e\r\n      \u003cspan data-t=\u0027{\"en\":\"A foreigner purchasing property through PDS, Smart City, or similar schemes at the minimum threshold automatically qualifies for a Permanent Residence Permit in Mauritius, valid for 20 years and renewable.\",\"fr\":\"Un \\u00e9tranger achetant un bien via le PDS, le Smart City ou des r\\u00e9gimes similaires au seuil minimum obtient automatiquement un Permis de r\\u00e9sidence permanente \\u00e0 Maurice, valable 20 ans et renouvelable.\"}\u0027\u003eA foreigner purchasing property through PDS, Smart City, or similar schemes at the minimum threshold automatically qualifies for a Permanent Residence Permit in Mauritius, valid for 20 years and renewable.\u003c/span\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"tags\"\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"PDS Scheme\",\"fr\":\"R\\u00e9gime PDS\"}\u0027\u003ePDS Scheme\u003c/span\u003e\r\n      \u003cspan class=\"tag\"\u003eSmart City\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"G+2 Scheme\",\"fr\":\"R\\u00e9gime G+2\"}\u0027\u003eG+2 Scheme\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"Residency by Investment\",\"fr\":\"R\\u00e9sidence par l\\u2019Investissement\"}\u0027\u003eResidency by Investment\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"No Capital Gains Tax\",\"fr\":\"Pas d\\u2019Imp\\u00f4t sur les Plus-values\"}\u0027\u003eNo Capital Gains Tax\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"EDB Approval Required\",\"fr\":\"Approbation EDB Requise\"}\u0027\u003eEDB Approval Required\u003c/span\u003e\r\n    \u003c/div\u003e\r\n  \u003c/section\u003e"},{"id":"southafrica","markup":"\u003csection class=\"country\" id=\"southafrica\"\u003e\r\n    \u003cdiv class=\"country-header\"\u003e\r\n      \u003cdiv class=\"country-flag\"\u003e\u0026#127487;\u0026#127462;\u003c/div\u003e\r\n      \u003cdiv class=\"country-title-block\"\u003e\r\n        \u003cdiv class=\"country-label\" data-t=\u0027{\"en\":\"Republic of South Africa\",\"fr\":\"R\\u00e9publique d\\u2019Afrique du Sud\"}\u0027\u003eRepublic of South Africa\u003c/div\u003e\r\n        \u003cdiv class=\"country-title\" data-t=\u0027{\"en\":\"Land Law in South Africa\",\"fr\":\"Droit Foncier en Afrique du Sud\"}\u0027\u003eLand Law in South Africa\u003c/div\u003e\r\n        \u003cdiv class=\"country-subtitle\" data-t=\u0027{\"en\":\"South Africa has a dual challenge: an open property market for foreigners alongside an ongoing land reform debate driven by historical dispossession.\",\"fr\":\"L\\u2019Afrique du Sud fait face \\u00e0 un double d\\u00e9fi\\u00a0: un march\\u00e9 immobilier ouvert aux \\u00e9trangers et un d\\u00e9bat persistant sur la r\\u00e9forme fonci\\u00e8re motiv\\u00e9 par les d\\u00e9possessions historiques.\"}\u0027\u003eSouth Africa has a dual challenge: an open property market for foreigners alongside an ongoing land reform debate driven by historical dispossession.\u003c/div\u003e\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"summary-card\"\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"South Africa currently allows foreigners to own land on the same basis as citizens, in freehold. However, land reform legislation \\u2014 including potential expropriation without compensation \\u2014 remains under active political and legal debate.\",\"fr\":\"L\\u2019Afrique du Sud permet actuellement aux \\u00e9trangers de poss\\u00e9der des terres dans les m\\u00eames conditions que les citoyens, en pleine propri\\u00e9t\\u00e9. Cependant, la l\\u00e9gislation sur la r\\u00e9forme fonci\\u00e8re \\u2014 y compris l\\u2019expropriation potentielle sans indemnisation \\u2014 fait toujours l\\u2019objet de d\\u00e9bats politiques et juridiques actifs.\"}\u0027\u003eSouth Africa currently allows foreigners to own land on the same basis as citizens, in freehold. However, land reform legislation \u0026mdash; including potential expropriation without compensation \u0026mdash; remains under active political and legal debate.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Constitutional Framework\",\"fr\":\"Cadre Constitutionnel\"}\u0027\u003eConstitutional Framework\u003c/h3\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"Section 25 of the Constitution of South Africa, 1996 (the Property Clause) protects individuals against arbitrary deprivation of property but also empowers the state to expropriate for public purposes, subject to just and equitable compensation. It further mandates land reform to redress historical inequalities caused by apartheid-era dispossession.\",\"fr\":\"L\\u2019article 25 de la Constitution de l\\u2019Afrique du Sud de 1996 (la \\u00ab Clause de propri\\u00e9t\\u00e9 \\u00bb) prot\\u00e8ge les individus contre toute privation arbitraire de biens, mais habilite \\u00e9galement l\\u2019\\u00c9tat \\u00e0 exproprier \\u00e0 des fins publiques, sous r\\u00e9serve d\\u2019une indemnisation juste et \\u00e9quitable. Il mandate en outre une r\\u00e9forme fonci\\u00e8re pour rem\\u00e9dier aux in\\u00e9galit\\u00e9s historiques caus\\u00e9es par les d\\u00e9possessions de l\\u2019\\u00e8re de l\\u2019apartheid.\"}\u0027\u003eSection 25 of the Constitution of South Africa, 1996 (the \u0026ldquo;Property Clause\u0026rdquo;) protects individuals against arbitrary deprivation of property but also empowers the state to expropriate for public purposes, subject to just and equitable compensation. It further mandates land reform to redress historical inequalities caused by apartheid-era dispossession.\u003c/p\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"The Expropriation Act 13 of 2024 allows in limited circumstances for expropriation at nil compensation for unused or abandoned land held for speculative purposes. The Act remains contested and is subject to constitutional challenges.\",\"fr\":\"La Loi d\\u2019expropriation 13 de 2024 permet dans des circonstances limit\\u00e9es l\\u2019expropriation \\u00e0 compensation nulle pour les terres inutilis\\u00e9es ou abandonn\\u00e9es d\\u00e9tenues \\u00e0 des fins sp\\u00e9culatives. La loi reste contest\\u00e9e et fait l\\u2019objet de recours constitutionnels.\"}\u0027\u003eThe \u003cstrong\u003eExpropriation Act 13 of 2024\u003c/strong\u003e allows in limited circumstances for expropriation at nil compensation for unused or abandoned land held for speculative purposes. The Act remains contested and is subject to constitutional challenges.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Key Legislation\",\"fr\":\"L\\u00e9gislation Principale\"}\u0027\u003eKey Legislation\u003c/h3\u003e\r\n      \u003ctable class=\"key-laws\"\u003e\r\n        \u003cthead\u003e\u003ctr\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Law / Decree\",\"fr\":\"Loi / D\\u00e9cret\"}\u0027\u003eLaw / Decree\u003c/th\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Year\",\"fr\":\"Ann\\u00e9e\"}\u0027\u003eYear\u003c/th\u003e\r\n          \u003cth data-t=\u0027{\"en\":\"Subject\",\"fr\":\"Objet\"}\u0027\u003eSubject\u003c/th\u003e\r\n        \u003c/tr\u003e\u003c/thead\u003e\r\n        \u003ctbody\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eConstitution, Section 25\u003c/td\u003e\u003ctd\u003e1996\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Property Clause: protection and expropriation framework\",\"fr\":\"Clause de propri\\u00e9t\\u00e9\\u00a0: protection et cadre d\\u2019expropriation\"}\u0027\u003eProperty Clause: protection and expropriation framework\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://www.gov.za/issues/land-reform\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"SA Government \\u2014 Land Reform\",\"fr\":\"Gouvernement SA \\u2014 R\\u00e9forme Fonci\\u00e8re\"}\u0027\u003eSA Government \u0026mdash; Land Reform\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eDeeds Registries Act (No. 47 of 1937)\u003c/td\u003e\u003ctd\u003e1937\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Registration of all real rights in land\",\"fr\":\"Enregistrement de tous les droits r\\u00e9els sur les terres\"}\u0027\u003eRegistration of all real rights in land\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://www.saflii.org/za/legis/consol_act/dra1937225/\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"SAFLII \\u2014 Full Text\",\"fr\":\"SAFLII \\u2014 Texte Int\\u00e9gral\"}\u0027\u003eSAFLII \u0026mdash; Full Text\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eRestitution of Land Rights Act (No. 22 of 1994)\u003c/td\u003e\u003ctd\u003e1994\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Claims by dispossessed persons or communities (post-1913)\",\"fr\":\"R\\u00e9clamations de personnes ou communaut\\u00e9s d\\u00e9poss\\u00e9d\\u00e9es (apr\\u00e8s 1913)\"}\u0027\u003eClaims by dispossessed persons or communities (post-1913)\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://www.saflii.org/za/legis/consol_act/rolra1994315/\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"SAFLII \\u2014 Full Text\",\"fr\":\"SAFLII \\u2014 Texte Int\\u00e9gral\"}\u0027\u003eSAFLII \u0026mdash; Full Text\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eLand Reform (Labour Tenants) Act (No. 3 of 1996)\u003c/td\u003e\u003ctd\u003e1996\u003c/td\u003e\u003ctd data-t=\u0027{\"en\":\"Rights of labour tenants; protection from eviction\",\"fr\":\"Droits des locataires agricoles\\u00a0; protection contre l\\u2019expulsion\"}\u0027\u003eRights of labour tenants; protection from eviction\u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eExtension of Security of Tenure Act (No. 62 of 1997)\u003c/td\u003e\u003ctd\u003e1997\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Protects occupiers of rural and peri-urban land from eviction\",\"fr\":\"Prot\\u00e8ge les occupants des terres rurales et p\\u00e9riurbaines contre l\\u2019expulsion\"}\u0027\u003eProtects occupiers of rural and peri-urban land from eviction\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://www.saflii.org/za/legis/consol_act/esota1997371/\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"SAFLII \\u2014 Full Text\",\"fr\":\"SAFLII \\u2014 Texte Int\\u00e9gral\"}\u0027\u003eSAFLII \u0026mdash; Full Text\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eSubdivision of Agricultural Land Act (No. 70 of 1970)\u003c/td\u003e\u003ctd\u003e1970\u003c/td\u003e\u003ctd data-t=\u0027{\"en\":\"Ministerial consent required to subdivide agricultural land\",\"fr\":\"Consentement minist\\u00e9riel requis pour subdiviser les terres agricoles\"}\u0027\u003eMinisterial consent required to subdivide agricultural land\u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eExpropriation Act (No. 13 of 2024)\u003c/td\u003e\u003ctd\u003e2024\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Updated expropriation framework; nil compensation in limited cases\",\"fr\":\"Cadre d\\u2019expropriation mis \\u00e0 jour\\u00a0; compensation nulle dans des cas limit\\u00e9s\"}\u0027\u003eUpdated expropriation framework; nil compensation in limited cases\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://www.parliament.gov.za/storage/app/media/Acts/2024/Act_13_of_2024_Expropriation_Act_2024.pdf\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"Parliament PDF\",\"fr\":\"PDF du Parlement\"}\u0027\u003eParliament PDF\u003c/a\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://www.saflii.org/za/legis/consol_act/ea13o2024207/\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"SAFLII \\u2014 Full Text\",\"fr\":\"SAFLII \\u2014 Texte Int\\u00e9gral\"}\u0027\u003eSAFLII \u0026mdash; Full Text\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n          \u003ctr\u003e\u003ctd class=\"law-name\"\u003eSpatial Planning and Land Use Management Act (No. 16 of 2013)\u003c/td\u003e\u003ctd\u003e2013\u003c/td\u003e\u003ctd\u003e\r\n            \u003cspan data-t=\u0027{\"en\":\"Land use planning; zoning; spatial development frameworks\",\"fr\":\"Planification de l\\u2019utilisation des terres\\u00a0; zonage\\u00a0; cadres de d\\u00e9veloppement spatial\"}\u0027\u003eLand use planning; zoning; spatial development frameworks\u003c/span\u003e\u003cbr\u003e\r\n            \u003ca class=\"doc-link\" href=\"https://www.saflii.org/za/legis/consol_act/spalumo2013484/\" target=\"_blank\" rel=\"noopener\" data-t=\u0027{\"en\":\"SAFLII \\u2014 Full Text\",\"fr\":\"SAFLII \\u2014 Texte Int\\u00e9gral\"}\u0027\u003eSAFLII \u0026mdash; Full Text\u003c/a\u003e\r\n          \u003c/td\u003e\u003c/tr\u003e\r\n        \u003c/tbody\u003e\r\n      \u003c/table\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"two-col\"\u003e\r\n      \u003cdiv class=\"info-box\"\u003e\r\n        \u003ch4 data-t=\u0027{\"en\":\"Citizen Rights\",\"fr\":\"Droits des Citoyens\"}\u0027\u003eCitizen Rights\u003c/h4\u003e\r\n        \u003cul\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Full freehold ownership rights\",\"fr\":\"Pleine propri\\u00e9t\\u00e9 fonci\\u00e8re\"}\u0027\u003eFull freehold ownership rights\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Eligible for land restitution claims\",\"fr\":\"\\u00c9ligible aux r\\u00e9clamations de restitution fonci\\u00e8re\"}\u0027\u003eEligible for land restitution claims\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Access to state land redistribution\",\"fr\":\"Acc\\u00e8s \\u00e0 la redistribution des terres de l\\u2019\\u00c9tat\"}\u0027\u003eAccess to state land redistribution\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Right to mortgage and bequeath freely\",\"fr\":\"Droit d\\u2019hypoth\\u00e9quer et de l\\u00e9guer librement\"}\u0027\u003eRight to mortgage and bequeath freely\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Protected against arbitrary dispossession\",\"fr\":\"Prot\\u00e9g\\u00e9 contre la d\\u00e9possession arbitraire\"}\u0027\u003eProtected against arbitrary dispossession\u003c/li\u003e\r\n        \u003c/ul\u003e\r\n      \u003c/div\u003e\r\n      \u003cdiv class=\"info-box\"\u003e\r\n        \u003ch4 data-t=\u0027{\"en\":\"Foreign National Rights\",\"fr\":\"Droits des Ressortissants \\u00c9trangers\"}\u0027\u003eForeign National Rights\u003c/h4\u003e\r\n        \u003cul\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Same freehold rights as citizens (currently)\",\"fr\":\"M\\u00eames droits de pleine propri\\u00e9t\\u00e9 que les citoyens (actuellement)\"}\u0027\u003eSame freehold rights as citizens (currently)\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"No restrictions on residential purchases\",\"fr\":\"Aucune restriction sur les achats r\\u00e9sidentiels\"}\u0027\u003eNo restrictions on residential purchases\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Agricultural land purchase without restriction\",\"fr\":\"Achat de terres agricoles sans restriction\"}\u0027\u003eAgricultural land purchase without restriction\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Subject to same transfer duty as residents\",\"fr\":\"Soumis aux m\\u00eames droits de mutation que les r\\u00e9sidents\"}\u0027\u003eSubject to same transfer duty as residents\u003c/li\u003e\r\n          \u003cli data-t=\u0027{\"en\":\"Watch: proposed foreign ownership caps\",\"fr\":\"Attention\\u00a0: plafonds de propri\\u00e9t\\u00e9 \\u00e9trang\\u00e8re propos\\u00e9s\"}\u0027\u003eWatch: proposed foreign ownership caps\u003c/li\u003e\r\n        \u003c/ul\u003e\r\n      \u003c/div\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Land Reform Programme\",\"fr\":\"Programme de R\\u00e9forme Fonci\\u00e8re\"}\u0027\u003eLand Reform Programme\u003c/h3\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"South Africa\\u2019s land reform programme has three pillars: restitution (returning land lost after 1913 to dispossessed communities), redistribution (transferring farmland through willing-seller/willing-buyer and state grants), and tenure reform (securing rights of farm workers and labour tenants). Since 1994, over 8 million hectares have been redistributed or restored.\",\"fr\":\"Le programme de r\\u00e9forme fonci\\u00e8re d\\u2019Afrique du Sud repose sur trois piliers\\u00a0: la restitution (restitution des terres perdues apr\\u00e8s 1913 aux communaut\\u00e9s d\\u00e9poss\\u00e9d\\u00e9es), la redistribution (transfert de terres agricoles via le m\\u00e9canisme vendeur/acheteur consentant et des subventions d\\u2019\\u00c9tat) et la r\\u00e9forme du r\\u00e9gime foncier (garantie des droits des travailleurs agricoles et locataires). Depuis 1994, plus de 8 millions d\\u2019hectares ont \\u00e9t\\u00e9 redistribu\\u00e9s ou restitu\\u00e9s.\"}\u0027\u003eSouth Africa\u0026rsquo;s land reform programme has three pillars: \u003cstrong\u003erestitution\u003c/strong\u003e (returning land lost after 1913 to dispossessed communities), \u003cstrong\u003eredistribution\u003c/strong\u003e (transferring farmland through willing-seller/willing-buyer and state grants), and \u003cstrong\u003etenure reform\u003c/strong\u003e (securing rights of farm workers and labour tenants). Since 1994, over 8 million hectares have been redistributed or restored.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"law-section\"\u003e\r\n      \u003ch3 data-t=\u0027{\"en\":\"Transfer Duties \u0026amp; Costs\",\"fr\":\"Droits de Mutation et Co\\u00fbts\"}\u0027\u003eTransfer Duties \u0026amp; Costs\u003c/h3\u003e\r\n      \u003cp data-t=\u0027{\"en\":\"Transfer duty is payable on property transactions above R1,100,000 (2024 threshold), on a progressive scale from 3% to 13%. Properties below this threshold are exempt. VAT at 15% applies where the seller is a VAT vendor, in which case transfer duty does not also apply.\",\"fr\":\"Le droit de mutation est payable pour les transactions immobili\\u00e8res sup\\u00e9rieures \\u00e0 1\\u00a0100\\u00a0000 R (seuil 2024), sur une \\u00e9chelle progressive de 3\\u00a0% \\u00e0 13\\u00a0%. Les biens inf\\u00e9rieurs \\u00e0 ce seuil sont exon\\u00e9r\\u00e9s. La TVA \\u00e0 15\\u00a0% s\\u2019applique lorsque le vendeur est un assujetti \\u00e0 la TVA, auquel cas le droit de mutation ne s\\u2019applique pas.\"}\u0027\u003eTransfer duty is payable on property transactions above R1,100,000 (2024 threshold), on a progressive scale from 3% to 13%. Properties below this threshold are exempt. VAT at 15% applies where the seller is a VAT vendor, in which case transfer duty does not also apply.\u003c/p\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"alert\"\u003e\r\n      \u003cstrong data-t=\u0027{\"en\":\"Expropriation Act 2024 \\u2014 Key Context\",\"fr\":\"Loi d\\u2019Expropriation 2024 \\u2014 Contexte Essentiel\"}\u0027\u003eExpropriation Act 2024 \u0026mdash; Key Context\u003c/strong\u003e\r\n      \u003cspan data-t=\u0027{\"en\":\"The Expropriation Act 13 of 2024 signed by President Ramaphosa in January 2025 does not amount to blanket land grabs. Nil compensation is only envisaged in specific, narrowly defined circumstances \\u2014 such as abandoned land held purely speculatively. The Act still requires due process and is subject to constitutional court scrutiny.\",\"fr\":\"La Loi d\\u2019expropriation 13 de 2024 sign\\u00e9e par le Pr\\u00e9sident Ramaphosa en janvier 2025 ne constitue pas une confiscation g\\u00e9n\\u00e9ralis\\u00e9e des terres. La compensation nulle n\\u2019est envisag\\u00e9e que dans des circonstances sp\\u00e9cifiques et \\u00e9troitement d\\u00e9finies \\u2014 comme les terres abandonn\\u00e9es d\\u00e9tenues \\u00e0 des fins purement sp\\u00e9culatives. La loi exige toujours un processus r\\u00e9gulier et fait l\\u2019objet d\\u2019un examen par la Cour constitutionnelle.\"}\u0027\u003eThe Expropriation Act 13 of 2024 signed by President Ramaphosa in January 2025 does not amount to blanket land grabs. Nil compensation is only envisaged in specific, narrowly defined circumstances \u0026mdash; such as abandoned land held purely speculatively. The Act still requires due process and is subject to constitutional court scrutiny.\u003c/span\u003e\r\n    \u003c/div\u003e\r\n    \u003cdiv class=\"tags\"\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"Freehold Open to Foreigners\",\"fr\":\"Pleine Propri\\u00e9t\\u00e9 Ouverte aux \\u00c9trangers\"}\u0027\u003eFreehold Open to Foreigners\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"Land Restitution\",\"fr\":\"Restitution Fonci\\u00e8re\"}\u0027\u003eLand Restitution\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"Expropriation Act 2024\",\"fr\":\"Loi d\\u2019Expropriation 2024\"}\u0027\u003eExpropriation Act 2024\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"Deeds Registry\",\"fr\":\"Registre des Actes\"}\u0027\u003eDeeds Registry\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"Land Claims Court\",\"fr\":\"Tribunal des R\\u00e9clamations Fonci\\u00e8res\"}\u0027\u003eLand Claims Court\u003c/span\u003e\r\n      \u003cspan class=\"tag\" data-t=\u0027{\"en\":\"Transfer Duty\",\"fr\":\"Droit de Mutation\"}\u0027\u003eTransfer Duty\u003c/span\u003e\r\n    \u003c/div\u003e\r\n  \u003c/section\u003e"}];
